Local launch defaults are kept out of the address bar. Explicit diagnostic overrides still work.
const profile = await fetch('/local-profile.json', {cache: 'no-store'}).then(r => { if (!r.ok) throw new Error('Local profile unavailable'); return r.json(); });
for (const [key, value] of Object.entries(profile)) if (!q.has(key)) q.set(key, String(value));
// A second engine competes for the exclusive OPFS cache and several GB of memory.
if (navigator.locks) {
 const owned = await new Promise(resolve => navigator.locks.request('gtav-local-engine', {ifAvailable: true}, lock => {
  resolve(!!lock);
  if (lock) return new Promise(release => addEventListener('pagehide', release, {once: true}));
 }));
 if (!owned) {
  document.body.innerHTML = '<div style="padding:40px;font:20px sans-serif">GTAV is already running in another tab. Return to that tab to play.</div>';
  throw new Error('Another GTAV tab owns the engine');
 }
} 
//

// Keep diagnostics useful without HTTP posts for every engine debug line.
const text = String(ev.data);
if (!/\[wgpu\]|\[io\]|THREAD ERROR|CRASH|Aborted|out of memory|loader:|\[loader\]/i.test(text)) return;
